from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class PlanInfoV1(SchemaObject):
    plan_id = SchemaField(name="plan_id", not_null=True)
    status = SchemaField(name="status", not_null=True)
    user_plan_id = SchemaField(name="user_plan_id", optional=True)
    plan_description = SchemaField(name="plan_description", optional=True)

    def __init__(self, plan_id, status, user_plan_id, plan_description):
        self.plan_id = plan_id
        self.status = status
        self.user_plan_id = user_plan_id
        self.plan_description = plan_description

        super(PlanInfoV1, self).__init__()
